std::string run_tests() {
    zq_passed = zq_failed = 0;
    for (const ZqTest& t : zq_registry()) {
        int before = zq_bad;
        t.fn();
        if (zq_bad == before) { ++zq_passed; std::printf("PASS %s\n", t.name); }
        else { ++zq_failed; std::printf("FAIL %s\n", t.name); }
    }
    return std::to_string(zq_passed) + " passed, " + std::to_string(zq_failed) + " failed";
}

